python3 -c "
import json
with open('/app/resources/treasury_bulletin_1969_01.json', 'r') as f:
    data = json.load(f)

# Search for interest in content
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'interest' in str(k).lower():
                print(f'Key: {path}.{k}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]')

search(data)
" 2>/dev/null | head -50

python3 -c "
import json
with open('/app/resources/treasury_bulletin_1969_01.json', 'r') as f:
    data = json.load(f)

# Search for 1961 in content
def search(obj, path='', depth=0):
    if depth > 4:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '1961' in str(k) or '1968' in str(k):
                print(f'Key: {path}.{k}')
            search(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, v in enumerate(obj[:10]):  # Limit
            search(v, f'{path}[{i}]', depth+1)

search(data)
" 2>/dev/null | head -30
